 * `apiSelectAllCurrentPage` - from API methods `selectAllOnCurrentPage`/`deselectAllOnCurrentPage`
 * - `checkboxSelected` - row selection checkbox clicked - `rowClicked` - row clicked when row
 * selection enabled - `rowDataChanged` - row data updated which triggered selection updates -
 * `rowGroupChanged` - grouping changed which updated the selection - `selectableChanged`-
 * selectable status of row has changed when `rowSelection.groupSelects` is `'descendants'` or
 * `'filteredDescendants'` - `spaceKey` - space key pressed on row - `keyboardSelectAll` - select
 * all via keyboard shortcut (CTRL+A) - `uiSelectAll` - select all in header clicked -
 * `uiSelectAllFiltered` - select all in header clicked when `rowSelection.selectAll = 'filtered'` -
 * `uiSelectAllCurrentPage` - select all in header clicked when `rowSelection.selectAll =
 * 'currentPage'` - `masterDetail` - Syncing selection state between master row and detail grid -
 * 'gridInitializing' - set as part of initial state while the grid is initializing
 */
sealed external interface SelectionEventSourceType

inline fun SelectionEventSourceType(value: String): SelectionEventSourceType = value.unsafeCast<SelectionEventSourceType>()

object SelectionEventSourceTypes {
    inline val api: SelectionEventSourceType get() = SelectionEventSourceType("api")
    inline val apiSelectAll: SelectionEventSourceType get() = SelectionEventSourceType("apiSelectAll")
    inline val apiSelectAllFiltered: SelectionEventSourceType get() = SelectionEventSourceType("apiSelectAllFiltered")
    inline val apiSelectAllCurrentPage: SelectionEventSourceType get() = SelectionEventSourceType("apiSelectAllCurrentPage")
    inline val checkboxSelected: SelectionEventSourceType get() = SelectionEventSourceType("checkboxSelected")
    inline val rowClicked: SelectionEventSourceType get() = SelectionEventSourceType("rowClicked")
    inline val rowDataChanged: SelectionEventSourceType get() = SelectionEventSourceType("rowDataChanged")
    inline val rowGroupChanged: SelectionEventSourceType get() = SelectionEventSourceType("rowGroupChanged")
    inline val selectableChanged: SelectionEventSourceType get() = SelectionEventSourceType("selectableChanged")
    inline val spaceKey: SelectionEventSourceType get() = SelectionEventSourceType("spaceKey")
    inline val keyboardSelectAll: SelectionEventSourceType get() = SelectionEventSourceType("keyboardSelectAll")
    inline val uiSelectAll: SelectionEventSourceType get() = SelectionEventSourceType("uiSelectAll")
    inline val uiSelectAllFiltered: SelectionEventSourceType get() = SelectionEventSourceType("uiSelectAllFiltered")
    inline val uiSelectAllCurrentPage: SelectionEventSourceType get() = SelectionEventSourceType("uiSelectAllCurrentPage")
    inline val masterDetail: SelectionEventSourceType get() = SelectionEventSourceType("masterDetail")
    inline val gridInitializing: SelectionEventSourceType get() = SelectionEventSourceType("gridInitializing")
}

